import { PKPass } from "passkit-generator";

interface MemberPassData {
  firstName: string;
  lastName: string;
  status: string;
  token: string;
  memberSince: string;
}

// Template images embedded as base64 (Vercel serverless can't read src/ at runtime)
const TEMPLATE_IMAGES: Record<string, Buffer> = {
  "icon.png": Buffer.from("", "base64"),
  "icon@2x.png": Buffer.from("", "base64"),
  "icon@3x.png": Buffer.from("", "base64"),
  "logo.png": Buffer.from("", "base64"),
  "logo@2x.png": Buffer.from("", "base64"),
  "logo@3x.png": Buffer.from("", "base64"),
};

// Decode base64 env var to Buffer
function envToBuffer(envVar: string): Buffer {
  const value = process.env[envVar];
  if (!value) {
    throw new Error(`Missing environment variable: ${envVar}`);
  }
  return Buffer.from(value, "base64");
}

// Status display mapping
const statusDisplay: Record<string, string> = {
  active: "Active",
  vip: "VIP",
  staff: "Staff",
  comp: "Comp",
};

export async function generateApplePass(member: MemberPassData): Promise<Buffer> {
  const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || "https://member.kingscourtboston.com";
  const scanUrl = `${baseUrl}/scan/m/${member.token}`;

  const pass = new PKPass(
    TEMPLATE_IMAGES,
    {
      wwdr: envToBuffer("APPLE_WWDR_CERT"),
      signerCert: envToBuffer("APPLE_PASS_CERT"),
      signerKey: envToBuffer("APPLE_PASS_KEY"),
      signerKeyPassphrase: process.env.APPLE_PASS_KEY_PASSPHRASE || "",
    },
    {
      formatVersion: 1,
      passTypeIdentifier: process.env.APPLE_PASS_TYPE_ID || "pass.com.kingscourtboston.membership",
      teamIdentifier: process.env.APPLE_TEAM_ID || "",
      serialNumber: member.token,
      organizationName: "Kings Court Boston",
      description: "Kings Court Boston Membership Card",
      foregroundColor: "rgb(255, 255, 255)",
      backgroundColor: "rgb(26, 10, 46)",
      labelColor: "rgb(200, 180, 255)",
      logoText: "Kings Court",
    }
  );

  // Set pass type to generic
  pass.type = "generic";

  // Add fields
  pass.primaryFields.push({
    key: "member",
    label: "MEMBER",
    value: `${member.firstName} ${member.lastName}`,
  });

  pass.secondaryFields.push(
    {
      key: "status",
      label: "STATUS",
      value: statusDisplay[member.status] || member.status,
    },
    {
      key: "since",
      label: "MEMBER SINCE",
      value: new Date(member.memberSince).toLocaleDateString("en-US", {
        month: "short",
        year: "numeric",
      }),
    }
  );

  pass.auxiliaryFields.push({
    key: "venue",
    label: "VENUE",
    value: "Kings Court Boston",
  });

  pass.backFields.push(
    {
      key: "website",
      label: "Website",
      value: "kingscourtboston.com",
    },
    {
      key: "cardUrl",
      label: "Digital Card",
      value: `${baseUrl}/m/${member.token}`,
    },
    {
      key: "info",
      label: "About",
      value: "Kings Court Boston — Boston's underground comedy club, coffee shop & creative venue. Show this pass at the door for check-in.",
    }
  );

  // Set the QR barcode
  pass.setBarcodes({
    format: "PKBarcodeFormatQR",
    message: scanUrl,
    messageEncoding: "iso-8859-1",
    altText: `${member.firstName} ${member.lastName}`,
  });

  const buffer = pass.getAsBuffer();
  return buffer;
}
